439: /* Sometimes we are forced to create a new reply node, and we can't append to
440:  * the previous one, when that happens, we wanna try to trim the unused space
441:  * at the end of the last reply node which we won't use anymore. */
442: void trimReplyUnusedTailSpace(client *c) {
443:     listNode *ln = listLast(c->reply);
444:     clientReplyBlock *tail = ln? listNodeValue(ln): NULL;
445: 
446:     /* Note that 'tail' may be NULL even if we have a tail node, becuase when
447:      * addDeferredMultiBulkLength() is used */
448:     if (!tail) return;
449: 
450:     /* We only try to trim the space is relatively high (more than a 1/4 of the
451:      * allocation), otherwise there's a high chance realloc will NOP.
452:      * Also, to avoid large memmove which happens as part of realloc, we only do
453:      * that if the used part is small.  */
454:     if (tail->size - tail->used > tail->size / 4 &&
455:         tail->used < PROTO_REPLY_CHUNK_BYTES)
456:     {
457:         size_t old_size = tail->size;
458:         tail = zrealloc(tail, tail->used + sizeof(clientReplyBlock));
459:         /* If realloc was a NOP, we got the same value which has internal frag */
460:         if (tail == listNodeValue(ln)) return;
461:         /* take over the allocation's internal fragmentation (at least for
462:          * memory usage tracking) */
463:         tail->size = zmalloc_usable(tail) - sizeof(clientReplyBlock);
464:         c->reply_bytes += tail->size - old_size;
465:         listNodeValue(ln) = tail;
466:     }
467: }
