481: /* Populate the length object and try gluing it to the next chunk. */
482: void setDeferredAggregateLen(client *c, void *node, long length, char prefix) {
483:     listNode *ln = (listNode*)node;
484:     clientReplyBlock *next;
485:     char lenstr[128];
486:     size_t lenstr_len = sprintf(lenstr, "%c%ld\r\n", prefix, length);
487: 
488:     /* Abort when *node is NULL: when the client should not accept writes
489:      * we return NULL in addReplyDeferredLen() */
490:     if (node == NULL) return;
491:     serverAssert(!listNodeValue(ln));
492: 
493:     /* Normally we fill this dummy NULL node, added by addReplyDeferredLen(),
494:      * with a new buffer structure containing the protocol needed to specify
495:      * the length of the array following. However sometimes when there is
496:      * little memory to move, we may instead remove this NULL node, and prefix
497:      * our protocol in the node immediately after to it, in order to save a
498:      * write(2) syscall later. Conditions needed to do it:
499:      *
500:      * - The next node is non-NULL,
501:      * - It has enough room already allocated
